//! Acceptance 1: `share-management/status` keeps the Python shape and the
//! three-state `gateway_running` evidence.
//!
//! The expected bodies come from `tests/fixtures/rust_console_reads_rev1.json`,
//! generated by `tests/generate_rust_console_reads_fixture.py` from the real
//! Python cloud `usagesrv.Handler`.

mod support;

use serde_json::{json, Value};

use support::*;
use um_console::share_read::ShareReadStore;

fn status(
    temp: &um_test_harness::TempDataDir,
    snapshot: Value,
    running: Option<bool>,
) -> (u16, Value, Option<String>) {
    let mut seams = StaticShareSeams::new();
    seams.broker_snapshot = Some(snapshot);
    seams.gateway_running = running;
    seams.maintenance = Some(json!({
        "checked_at": 1700000000,
        "instance": {"active_count": 3},
    }));
    seams.attribution = Some(json!({
        "file_ready": true,
        "file_reason": "ok",
        "key_file": "/run/um-share/run/share-attribution.key",
        "key_chars": 43,
        "instance_loaded": {"value": "unknown"},
        "request_attribution_observed": false,
    }));
    let console = start_console_with_seams(
        temp,
        |config| {
            config.share_store_file = Some(temp.path().join("share.db"));
            config.public_origin = Some("https://share.example.test".to_string());
        },
        std::sync::Arc::new(seams),
    );
    let response = client_request(
        console.addr,
        &ClientRequest::get("/api/console/share-management/status"),
    )
    .expect("request");
    let mut body = response.json();
    if let Some(object) = body.as_object_mut() {
        object.remove("last_check_at");
    }
    (
        response.status,
        body,
        response.header("cache-control").map(str::to_string),
    )
}

#[test]
fn status_reshapes_the_share_manager_and_keeps_gateway_running_three_state() {
    let fixture = reads_fixture();
    let temp = temp();
    let store_seed = &fixture["shareStatus"]["storeSeed"];
    seed_share_store(&temp, store_seed);
    let cases = fixture["shareStatus"]["cases"].as_object().expect("cases");
    let snapshots = [
        (
            "confirmedRunning",
            json!({
                "name": "broker-client",
                "state": "ok",
                "broker": {
                    "version": "2.0.0",
                    "pid": 4242,
                    "diag": [{"stage": "publish", "ok": true}],
                },
            }),
            Some(true),
        ),
        (
            "confirmedStopped",
            json!({
                "name": "broker-client",
                "state": "unavailable",
                "error_code": "deadline_exceeded",
            }),
            Some(false),
        ),
        (
            "unconfirmed",
            json!({
                "name": "noop",
                "state": "offline",
                "note": "未安装/未授权高权限 broker；变更已保存但未在线发布",
            }),
            None,
        ),
    ];
    for (name, snapshot, running) in snapshots {
        let expected = &cases[name];
        let (status, body, cache_control) = status(&temp, snapshot, running);
        assert_eq!(
            u64::from(status),
            expected["status"].as_u64().unwrap(),
            "{name}"
        );
        assert_eq!(body, expected["body"], "{name}");
        assert_eq!(
            cache_control.as_deref(),
            expected["cacheControl"].as_str(),
            "{name}"
        );
        match running {
            Some(running) => {
                assert_eq!(body["gateway_running"], json!(running), "{name}");
            }
            None => {
                assert_eq!(body.get("gateway_running"), None, "{name}");
            }
        }
    }
}

#[test]
fn status_never_folds_unconfirmed_into_false() {
    let temp = temp();
    seed_share_store(&temp, &reads_fixture()["shareStatus"]["storeSeed"]);
    let mut seams = StaticShareSeams::new();
    seams.gateway_running = None;
    let store = ShareReadStore::new(temp.path().join("share.db"));
    let payload = store.status(&seams).expect("status");
    assert!(payload.get("gateway_running").is_none());
    assert_eq!(payload["capacity"]["in_flight"], json!(null));
    assert_eq!(
        payload["capacity"]["in_flight_reason"],
        json!("maintenance_unwired")
    );
}

#[test]
fn status_omits_share_url_when_the_public_origin_is_unconfigured() {
    let temp = temp();
    seed_share_store(&temp, &reads_fixture()["shareStatus"]["storeSeed"]);
    let mut seams = StaticShareSeams::new();
    seams.gateway_running = Some(false);
    let store = ShareReadStore::new(temp.path().join("share.db"));
    let mut payload = store.status(&seams).expect("status");
    assert_eq!(payload["share_url_source"], json!(null));
    assert_eq!(
        payload["share_url_reason"],
        json!("public_origin_unconfigured")
    );
    assert!(payload.get("share_url").is_none());
    let object = payload.as_object_mut().expect("object");
    object.remove("last_check_at");
    assert!(object.get("share_url").is_none());
}

#[test]
fn status_does_not_create_a_missing_share_store() {
    let temp = temp();
    let path = temp.path().join("missing-share.db");
    let store = ShareReadStore::new(path.clone());
    let error = store
        .status(&StaticShareSeams::new())
        .expect_err("missing store");
    assert_eq!(error.status, 500);
    assert_eq!(error.body["error"], json!("share management error"));
    assert!(!path.exists());
}
